{
  "findings": [
    {
      "check_id": "CKV_AWS_24",
      "title": "Instance without root block device encryption",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "HIGH",
      "explanation": "The EC2 instance does not specify encryption for its root block device. Unencrypted root volumes can expose sensitive data if the volume is compromised."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"MyFirstInstnace\" {\n  ami           = lookup(var.AMIS, var.AWS_REGION)\n  instance_type = \"t2.micro\"\n  availability_zone = \"us-east-2a\"\n  key_name      = aws_key_pair.levelup_key.key_name\n  vpc_security_group_ids = [aws_security_group.allow-levelup-ssh.id]\n  subnet_id = aws_subnet.levelupvpc-public-1.id\n\n  root_block_device {\n    encrypted = true\n  }\n}",
  "fix_summary": "Added encryption to the root block device of the EC2 instance to ensure data at rest is protected."
}
